import React, { useEffect, useRef } from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, Animated, Platform, Easing } from 'react-native';
import Svg, { Defs, LinearGradient, Stop, Rect } from 'react-native-svg';
import { useThemeStore } from '../store';
import { getGreeting } from '../utils';
import Icon from './Icon';
import VelarisShader from './VelarisShader';

interface GreetingHeaderProps {
  greetingText?: string;
  loading?: boolean;
  onPillPress?: (pillLabel: string) => void;
  colors?: string[];
  bg?: string;
  speed?: number;
  grain?: number;
}

const PILLS = [
  { label: 'Songs', icon: 'songs' as const },
  { label: 'Albums', icon: 'library' as const },
  { label: 'Playlists', icon: 'music' as const },
  { label: 'Liked Songs', icon: 'heart' as const },
];

export const MULTICOLOR_PALETTES = {
  morning: ['#f43f5e', '#a855f7', '#06b6d4', '#10b981'],   // Rose, Violet, Cyan, Emerald
  afternoon: ['#6366f1', '#06b6d4', '#10b981', '#ec4899'], // Indigo, Cyan, Emerald, Pink
  evening: ['#f97316', '#a855f7', '#3b82f6', '#10b981'],   // Sunset Orange, Violet, Blue, Emerald
  default: ['#f43f5e', '#a855f7', '#06b6d4', '#10b981'],   // Vibrant Multi-Color Aurora
};

const resolveHeaderColors = (textStr: string, customColors?: string[]): string[] => {
  if (customColors && customColors.length >= 4) return customColors;
  const lower = textStr.toLowerCase();
  if (lower.includes('morning')) return MULTICOLOR_PALETTES.morning;
  if (lower.includes('afternoon')) return MULTICOLOR_PALETTES.afternoon;
  if (lower.includes('evening')) return MULTICOLOR_PALETTES.evening;
  return MULTICOLOR_PALETTES.default;
};

export const GreetingHeader: React.FC<GreetingHeaderProps> = ({
  greetingText,
  loading = false,
  onPillPress,
  colors,
  bg = '#000000',
  speed = 3.5,
  grain = 0.3,
}) => {
  const { theme } = useThemeStore();
  const pulseAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (process.env.NODE_ENV === 'test') return;
    // Smooth infinite breathing pulse animation (4 second cycle)
    const animation = Animated.loop(
      Animated.sequence([
        Animated.timing(pulseAnim, {
          toValue: 1,
          duration: 2400,
          easing: Easing.inOut(Easing.ease),
          useNativeDriver: true,
        }),
        Animated.timing(pulseAnim, {
          toValue: 0,
          duration: 2400,
          easing: Easing.inOut(Easing.ease),
          useNativeDriver: true,
        }),
      ])
    );
    animation.start();
    return () => animation.stop();
  }, [pulseAnim]);

  const glowOpacity = pulseAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [0.35, 0.75],
  });

  const glowScale = pulseAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [1, 1.04],
  });

  const text = greetingText || getGreeting();
  const headerColors = resolveHeaderColors(text, colors);

  const animatedTranslateX = pulseAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [-20, 20],
  });

  const animatedScale = pulseAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [0.95, 1.12],
  });

  return (
    <VelarisShader
      bg={bg}
      colors={headerColors}
      speed={speed}
      grain={grain}
      style={styles.container}
    >
      {/* Background layer for Native platforms */}
      {Platform.OS !== 'web' && (
        <View style={[StyleSheet.absoluteFill, { backgroundColor: '#090a0f', overflow: 'hidden' }]}>
          <Animated.View
            style={[
              StyleSheet.absoluteFill,
              {
                backgroundColor: headerColors[1] || '#a855f7',
                opacity: glowOpacity,
                transform: [
                  { translateX: animatedTranslateX },
                  { scale: animatedScale },
                ],
              },
            ]}
          />
          <Svg height="100%" width="100%" style={StyleSheet.absoluteFill}>
            <Defs>
              <LinearGradient id="heroGradient" x1="0" y1="0" x2="1" y2="1">
                <Stop offset="0%" stopColor={headerColors[0]} stopOpacity="0.8" />
                <Stop offset="35%" stopColor={headerColors[1]} stopOpacity="0.7" />
                <Stop offset="70%" stopColor={headerColors[2]} stopOpacity="0.8" />
                <Stop offset="100%" stopColor={headerColors[3]} stopOpacity="0.95" />
              </LinearGradient>
            </Defs>
            <Rect x="0" y="0" width="100%" height="100%" fill="url(#heroGradient)" />
          </Svg>
        </View>
      )}

      {/* Content Container */}
      <View style={styles.content}>
        <View style={styles.greetingHeaderRow}>
          <Text style={styles.greetingText}>{text}</Text>
          <View style={styles.sparkleBadge}>
            <Icon name="music" size={14} color="#1DB954" />
          </View>
        </View>

        {/* Quick Filter Pills - Always rendered for consistent layout before & after loading */}
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.pillRow}
          style={styles.pillScroll}
        >
          {PILLS.map((pill) => (
            <TouchableOpacity
              key={pill.label}
              style={styles.pill}
              activeOpacity={0.75}
              onPress={() => onPillPress?.(pill.label)}
              accessibilityRole="button"
              accessibilityLabel={pill.label}
            >
              <Icon name={pill.icon} size={14} color="#FFFFFF" />
              <Text style={styles.pillText}>{pill.label}</Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>
    </VelarisShader>
  );
};

const styles = StyleSheet.create({
  container: {
    position: 'relative',
    paddingTop: Platform.OS === 'web' ? 24 : 48,
    paddingBottom: 20,
    borderBottomLeftRadius: 28,
    borderBottomRightRadius: 28,
    overflow: 'hidden',
    backgroundColor: '#242424',
  },
  shaderWrapper: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: '52%',
    overflow: 'hidden',
  },
  animatedGlowUpper: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: '60%',
    backgroundColor: 'rgba(6, 153, 102, 0.15)',
    borderTopLeftRadius: 28,
    borderTopRightRadius: 28,
  },
  content: {
    position: 'relative',
    zIndex: 2,
  },
  greetingHeaderRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 20,
    paddingTop: 8,
    paddingBottom: 8,
  },
  splitDividerLine: {
    height: 1.5,
    marginHorizontal: 20,
    marginVertical: 10,
    backgroundColor: 'rgba(255, 255, 255, 0.28)',
    borderRadius: 1,
    shadowColor: '#1DB954',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.8,
    shadowRadius: 3,
  },
  greetingText: {
    fontSize: 28,
    fontWeight: '800',
    color: '#FFFFFF',
    letterSpacing: -0.8,
    textShadowColor: 'rgba(0, 0, 0, 0.4)',
    textShadowOffset: { width: 0, height: 2 },
    textShadowRadius: 6,
  },
  sparkleBadge: {
    width: 32,
    height: 32,
    borderRadius: 16,
    backgroundColor: 'rgba(255, 255, 255, 0.12)',
    alignItems: 'center',
    justifyContent: 'center',
    borderWidth: 1,
    borderColor: 'rgba(255, 255, 255, 0.18)',
  },
  pillScroll: {
    marginTop: 4,
  },
  pillRow: {
    paddingHorizontal: 20,
    gap: 8,
  },
  pill: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
    paddingVertical: 8,
    paddingHorizontal: 16,
    borderRadius: 20,
    backgroundColor: 'rgba(255, 255, 255, 0.14)',
    borderWidth: 1,
    borderColor: 'rgba(255, 255, 255, 0.22)',
  },
  pillText: {
    fontSize: 13,
    fontWeight: '600',
    color: '#FFFFFF',
  },
});

export default GreetingHeader;
